const all = $input.all(); const raw = all[0].json;
const leads = Array.isArray(raw) ? raw : all.map(i => i.json);
return leads.map(l => ({ json: l }));

const openAiResponse = $input.first().json;
const mensagem = openAiResponse?.choices?.[0]?.message?.content ?? '';
const lead = $('Loop 1 lead por vez').item.json;

function normalizePhone(value) {
  let digits = String(value || '').replace(/\D/g, '');
  if (digits.startsWith('00')) digits = digits.slice(2);
  digits = digits.replace(/^0+/, '');
  if (!digits.startsWith('55') && (digits.length === 10 || digits.length === 11)) {
    digits = '55' + digits;
  }
  return digits;
}

if (!mensagem) throw new Error('OpenAI nao retornou mensagem: ' + JSON.stringify(openAiResponse).slice(0, 200));

const phone = normalizePhone(lead.whatsapp || lead.phone);

return [{
  json: {
    lead_id:       lead.id,
    phone,
    whatsapp:      phone,
    raw_phone:     lead.phone,
    business_name: lead.business_name,
    first_message: mensagem.trim().replace(/^["']|["']$/g, ''),
  }
}];

const waitSeconds  = Math.floor(Math.random() * 91) + 90;
const typingMs     = Math.floor(Math.random() * 4000) + 5000;
const lead = $('Extrai mensagem gerada').item.json;

return [{
  json: {
    wait_seconds:  waitSeconds,
    typing_ms:     typingMs,
    lead_id:       lead.lead_id,
    phone:         lead.phone,
    first_message: lead.first_message,
    business_name: lead.business_name,
  }
}];

// Apos o wait, $json = lead data (wait node passa o input adiante)
// Fazemos tudo em um code node para nao perder o contexto apos HTTP responses
const d = $json;
const rawPhone = d.whatsapp || d.phone;
const message = String(d.first_message || '').trim();
const typingMs = d.typing_ms || 8000;
const EVOLUTION_KEY = $env.EVOLUTION_API_KEY;
const BASE = 'https://evolutionapi.viniciusguilherme.shop';
const INST = 'vamo';

function normalizeBrazilPhone(value) {
  let digits = String(value || '').replace(/\D/g, '');
  if (digits.startsWith('00')) digits = digits.slice(2);
  digits = digits.replace(/^0+/, '');
  if (!digits.startsWith('55') && (digits.length === 10 || digits.length === 11)) {
    digits = '55' + digits;
  }
  return digits;
}

function phoneVariants(value) {
  const base = normalizeBrazilPhone(value);
  const result = [];
  const add = (phone) => {
    if (/^55\d{10,11}$/.test(phone) && !result.includes(phone)) result.push(phone);
  };

  add(base);

  if (base.startsWith('55')) {
    const local = base.slice(2);
    const ddd = local.slice(0, 2);
    const number = local.slice(2);

    if (local.length === 11 && number[0] === '9') {
      add('55' + ddd + number.slice(1));
    }
    if (local.length === 10) {
      add('55' + ddd + '9' + number);
    }
  }

  return result;
}

function isInvalidPhoneResponse(resp) {
  const text = JSON.stringify(resp || {}).toLowerCase();
  const messages = Array.isArray(resp?.response?.message) ? resp.response.message : [];
  return Boolean(
    resp?.exists === false ||
    resp?.status === 400 ||
    messages.some((item) => item && item.exists === false) ||
    text.includes('invalid_phone') ||
    text.includes('not exists') ||
    text.includes('does not exist')
  );
}

async function postEvolution(path, body) {
  return await this.helpers.httpRequest({
    method: 'POST',
    url: BASE + path,
    headers: { apikey: EVOLUTION_KEY, 'Content-Type': 'application/json' },
    body,
    ignoreHttpStatusErrors: true
  });
}

const candidates = phoneVariants(rawPhone);
if (!message) {
  return [{ json: { ...d, send_status: 'send_error', send_error: 'Mensagem vazia', phone_candidates: candidates } }];
}
if (!candidates.length) {
  return [{ json: { ...d, send_status: 'invalid_phone', send_error: 'Telefone sem DDI/DDD valido', phone_candidates: candidates } }];
}

// Envia indicador de digitando. Para Evolution, usamos numero limpo, sem sufixo JID.
try {
  await postEvolution.call(this, '/chat/sendPresence/' + INST, {
    number: candidates[0],
    delay: typingMs,
    presence: 'composing'
  });
} catch (e) { /* ignora erro de presence */ }

await new Promise((resolve) => setTimeout(resolve, typingMs));

const attempts = [];
let resp = {};
let phoneUsed = candidates[0];
let sent = false;

for (const candidate of candidates) {
  phoneUsed = candidate;
  try {
    // message/sendText deve receber apenas digitos. Nao usar sufixo JID aqui.
    resp = await postEvolution.call(this, '/message/sendText/' + INST, {
      number: candidate,
      text: message
    });
  } catch (e) {
    resp = { error: e.message };
  }

  attempts.push({ phone: candidate, response: resp });

  if (!isInvalidPhoneResponse(resp)) {
    sent = true;
    break;
  }
}

return [{
  json: {
    ...d,
    phone: phoneUsed,
    phone_candidates: candidates,
    evolution_response: resp,
    evolution_attempts: attempts,
    send_status: sent ? 'sent' : 'invalid_phone'
  }
}];

