={{ (() => {
  const sent = $json.send_status === 'sent';
  const body = {
    status: $json.send_status,
    next_followup_at: sent ? new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString() : null
  };
  if (sent) {
    body.sent_at = new Date().toISOString();
    body.sdr_history = [{ role: 'assistant', content: $json.first_message, ts: new Date().toISOString(), type: 'outbound' }];
  }
  return JSON.stringify(body);
})() }}
